// tenancy fills what the schema says this row's tenant is, and refuses a
// row whose other paths do not agree with it.
//
// The request is already this server's copy by the time it arrives, so it
// is written to rather than cloned again.
func (s sinkCustodyLine) tenancy(ctx context.Context, req *rove.CustodyLineAddRequest) error {
	want, err := s.tenantAtTenant(ctx, req.GetTenant())
	if err != nil {
		return err
	}

	if req.HasCustody() {
		got, err := s.tenantAtCustodyTenant(ctx, req.GetCustody())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("custody",
				"it is in another tenant than tenant")
		}
	}

	if req.HasAsset() {
		got, err := s.tenantAtAssetTenant(ctx, req.GetAsset())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("asset",
				"it is in another tenant than tenant")
		}
	}

	if req.HasStock() {
		got, err := s.tenantAtStockTenant(ctx, req.GetStock())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("stock",
				"it is in another tenant than tenant")
		}
	}

	return nil
}

// Add stamps this row's tenant before writing it.
func (s sinkCustodyLine) Add(ctx context.Context, req *rove.CustodyLineAddRequest) (*rove.CustodyLine, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding.
	r := proto.CloneOf(req)
	if err := s.tenancy(ctx, r); err != nil {
		return nil, err
	}

	return s.CustodyLineServiceServer.Add(ctx, r)
}

// orderCustodyLine is how CustodyLines come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderCustodyLine = []sqlpage.Order{
	{Column: custodyline.FieldDateCreated, Desc: false},
	{Column: custodyline.FieldId, Desc: false},
}

const (
	// CustodyLinePageSize is what a request that did not say gets, and
	// CustodyLinePageLimit is the most it gets however loudly it asks.
	CustodyLinePageSize  = 200
	CustodyLinePageLimit = 1000

	// CustodyLineFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	CustodyLineFilterLimit = 32
)

// List answers with the CustodyLines that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkCustodyLine) List(ctx context.Context, req *rove.CustodyLineListRequest) (*rove.CustodyLineListResponse, error) {
	q := s.store.Db.CustodyLine.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.CustodyLineNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > CustodyLineFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), CustodyLineFilterLimit)
		}

		ps := make([]predicate.CustodyLine, 0, len(fs))
		for i, f := range fs {
			p, err := filterCustodyLine(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(custodyline.Or(ps...))
	}

	if v := req.GetAfter(); v != "" {
		var (
			at0 time.Time
			at1 uuid.UUID
		)
		if err := sqlpage.Decode(v, &at0, &at1); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		p, err := sqlpage.After(orderCustodyLine, []any{at0, at1})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), CustodyLinePageSize, CustodyLinePageLimit)
	us, err := q.Order(custodyline.ByDateCreated(), custodyline.ById()).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.CustodyLine, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.CustodyLineListResponse_builder{Items: items}.Build()
	if more {
		last := us[len(us)-1]
		next, err := sqlpage.Encode(last.DateCreated, last.Id)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(next)
	}

	return res, nil
}

// filterCustodyLine turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterCustodyLine(f *rove.CustodyLineFilter) (predicate.CustodyLine, error) {
	ps := make([]predicate.CustodyLine, 0, 1)
	if f.HasRef() {
		p, err := bare.CustodyLinePick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasCustody() {
		w := f.GetCustody()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "custody: %s", err)
			}

			ps = append(ps, custodyline.CustodyIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.CustodyPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, custodyline.HasCustodyWith(q))
		}
	}
	if f.HasAsset() {
		w := f.GetAsset()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "asset: %s", err)
			}

			ps = append(ps, custodyline.AssetIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.AssetPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, custodyline.HasAssetWith(q))
		}
	}
	if f.HasStock() {
		w := f.GetStock()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "stock: %s", err)
			}

			ps = append(ps, custodyline.StockIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.StockPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, custodyline.HasStockWith(q))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return custodyline.And(ps...), nil
}

