// tenantAtTenant is the tenant "tenant" arrives at.
func (s sinkLink) tenantAtTenant(ctx context.Context, ref *rove.TenantRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("tenant", "required: it is what says which tenant this belongs to")
	}

	// The row the edge names, picked the way every other reference is.
	pick, err := bare.TenantPick(ref)
	if err != nil {
		return nil, pderr.At("tenant", err)
	}

	k, err := s.store.Db.Tenant.Query().Where(pick).OnlyId(ctx)
	if err != nil {
		// Not there, or more than one -- both are the reference being wrong,
		// and both are the caller's to fix.
		return nil, pderr.Invalidf("tenant", "it does not name one row")
	}

	return k[:], nil
}

// tenantAtSourceTenant is the tenant "source.tenant" arrives at.
func (s sinkLink) tenantAtSourceTenant(ctx context.Context, ref *rove.AssetRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("source", "required: it is what says which tenant this belongs to")
	}

	// The row the edge names, picked the way every other reference is.
	pick, err := bare.AssetPick(ref)
	if err != nil {
		return nil, pderr.At("source", err)
	}

	k, err := s.store.Db.Asset.Query().Where(pick).QueryTenant().OnlyId(ctx)
	if err != nil {
		// Not there, or more than one -- both are the reference being wrong,
		// and both are the caller's to fix.
		return nil, pderr.Invalidf("source", "it does not name one row")
	}

	return k[:], nil
}

// tenantAtTargetTenant is the tenant "target.tenant" arrives at.
