// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderLink = []sqlpage.Order{
	{Column: link.FieldDateCreated, Desc: false},
	{Column: link.FieldId, Desc: false},
}

const (
	// LinkPageSize is what a request that did not say gets, and
	// LinkPageLimit is the most it gets however loudly it asks.
	LinkPageSize  = 100
	LinkPageLimit = 1000

	// LinkFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	LinkFilterLimit = 32
)

// List answers with the Links that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkLink) List(ctx context.Context, req *rove.LinkListRequest) (*rove.LinkListResponse, error) {
	q := s.store.Db.Link.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.LinkNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > LinkFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), LinkFilterLimit)
		}

		ps := make([]predicate.Link, 0, len(fs))
		for i, f := range fs {
			p, err := filterLink(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(link.Or(ps...))
	}

	if v := req.GetAfter(); v != "" {
		var (
			at0 time.Time
			at1 uuid.UUID
		)
		if err := sqlpage.Decode(v, &at0, &at1); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		p, err := sqlpage.After(orderLink, []any{at0, at1})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), LinkPageSize, LinkPageLimit)
	us, err := q.Order(link.ByDateCreated(), link.ById()).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.Link, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.LinkListResponse_builder{Items: items}.Build()
	if more {
		last := us[len(us)-1]
		next, err := sqlpage.Encode(last.DateCreated, last.Id)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(next)
	}

	return res, nil
}

// filterLink turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterLink(f *rove.LinkFilter) (predicate.Link, error) {
	ps := make([]predicate.Link, 0, 1)
	if f.HasRef() {
		p, err := bare.LinkPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasSource() {
		w := f.GetSource()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "source: %s", err)
			}

			ps = append(ps, link.SourceIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.AssetPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, link.HasSourceWith(q))
		}
	}
	if f.HasTarget() {
		w := f.GetTarget()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "target: %s", err)
			}

			ps = append(ps, link.TargetIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.AssetPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, link.HasTargetWith(q))
		}
	}
	if f.HasKind() {
		ps = append(ps, link.KindEQ(f.GetKind()))
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return link.And(ps...), nil
}

type sinkNotification struct {
	rove.NotificationServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) Notification() rove.NotificationServiceServer {
	return sinkNotification{s.Server.Notification(), s.Server.Store, s.w, s.namer, s.joined}
}

// tenantAtTenant is the tenant "tenant" arrives at.
func (s sinkNotification) tenantAtTenant(ctx context.Context, ref *rove.TenantRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("tenant", "required: it is what says which tenant this belongs to")
	}

	// The row the edge names, picked the way every other reference is.
	pick, err := bare.TenantPick(ref)
	if err != nil {
		return nil, pderr.At("tenant", err)
	}

	k, err := s.store.Db.Tenant.Query().Where(pick).OnlyId(ctx)
	if err != nil {
		// Not there, or more than one -- both are the reference being wrong,
		// and both are the caller's to fix.
		return nil, pderr.Invalidf("tenant", "it does not name one row")
	}

	return k[:], nil
}

// tenantAtHolderTenant is the tenant "holder.tenant" arrives at.
func (s sinkNotification) tenantAtHolderTenant(ctx context.Context, ref *rove.HolderRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("holder", "required: it is what says which tenant this belongs to")
	}

	// The row the edge names, picked the way every other reference is.
	pick, err := bare.HolderPick(ref)
	if err != nil {
		return nil, pderr.At("holder", err)
	}

	k, err := s.store.Db.Holder.Query().Where(pick).QueryTenant().OnlyId(ctx)
	if err != nil {
		// Not there, or more than one -- both are the reference being wrong,
		// and both are the caller's to fix.
		return nil, pderr.Invalidf("holder", "it does not name one row")
	}

	return k[:], nil
}

// tenancy fills what the schema says this row's tenant is, and refuses a
// row whose other paths do not agree with it.
//
// The request is already this server's copy by the time it arrives, so it
// is written to rather than cloned again.
func (s sinkNotification) tenancy(ctx context.Context, req *rove.NotificationAddRequest) error {
	want, err := s.tenantAtTenant(ctx, req.GetTenant())
	if err != nil {
		return err
	}

	if req.HasHolder() {
		got, err := s.tenantAtHolderTenant(ctx, req.GetHolder())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("holder",
				"it is in another tenant than tenant")
		}
	}

	return nil
}

// Add stamps this row's tenant before writing it.
func (s sinkNotification) Add(ctx context.Context, req *rove.NotificationAddRequest) (*rove.Notification, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding.
	r := proto.CloneOf(req)
	if err := s.tenancy(ctx, r); err != nil {
		return nil, err
	}

	return s.NotificationServiceServer.Add(ctx, r)
}

// orderNotification is how Notifications come back.
