// orderPurchaseLine is how PurchaseLines come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderPurchaseLine = []sqlpage.Order{
	{Column: purchaseline.FieldDateCreated, Desc: false},
	{Column: purchaseline.FieldId, Desc: false},
}

const (
	// PurchaseLinePageSize is what a request that did not say gets, and
	// PurchaseLinePageLimit is the most it gets however loudly it asks.
	PurchaseLinePageSize  = 200
	PurchaseLinePageLimit = 1000

	// PurchaseLineFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	PurchaseLineFilterLimit = 32
)

// List answers with the PurchaseLines that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkPurchaseLine) List(ctx context.Context, req *rove.PurchaseLineListRequest) (*rove.PurchaseLineListResponse, error) {
	q := s.store.Db.PurchaseLine.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.PurchaseLineNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > PurchaseLineFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), PurchaseLineFilterLimit)
		}

		ps := make([]predicate.PurchaseLine, 0, len(fs))
		for i, f := range fs {
			p, err := filterPurchaseLine(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(purchaseline.Or(ps...))
	}

	if v := req.GetAfter(); v != "" {
		var (
			at0 time.Time
			at1 uuid.UUID
		)
		if err := sqlpage.Decode(v, &at0, &at1); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		p, err := sqlpage.After(orderPurchaseLine, []any{at0, at1})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), PurchaseLinePageSize, PurchaseLinePageLimit)
	us, err := q.Order(purchaseline.ByDateCreated(), purchaseline.ById()).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.PurchaseLine, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.PurchaseLineListResponse_builder{Items: items}.Build()
	if more {
		last := us[len(us)-1]
		next, err := sqlpage.Encode(last.DateCreated, last.Id)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(next)
	}

	return res, nil
}

// filterPurchaseLine turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterPurchaseLine(f *rove.PurchaseLineFilter) (predicate.PurchaseLine, error) {
	ps := make([]predicate.PurchaseLine, 0, 1)
	if f.HasRef() {
		p, err := bare.PurchaseLinePick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasPurchase() {
		w := f.GetPurchase()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "purchase: %s", err)
			}

			ps = append(ps, purchaseline.PurchaseIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.PurchasePick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, purchaseline.HasPurchaseWith(q))
		}
	}
	if f.HasModel() {
		w := f.GetModel()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "model: %s", err)
			}

			ps = append(ps, purchaseline.ModelIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.ItemModelPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, purchaseline.HasModelWith(q))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return purchaseline.And(ps...), nil
}

