// orderReservationItem is how ReservationItems come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderReservationItem = []sqlpage.Order{
	{Column: reservationitem.FieldDateCreated, Desc: false},
	{Column: reservationitem.FieldId, Desc: false},
}

const (
	// ReservationItemPageSize is what a request that did not say gets, and
	// ReservationItemPageLimit is the most it gets however loudly it asks.
	ReservationItemPageSize  = 100
	ReservationItemPageLimit = 500

	// ReservationItemFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	ReservationItemFilterLimit = 32
)

// List answers with the ReservationItems that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkReservationItem) List(ctx context.Context, req *rove.ReservationItemListRequest) (*rove.ReservationItemListResponse, error) {
	q := s.store.Db.ReservationItem.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.ReservationItemNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > ReservationItemFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), ReservationItemFilterLimit)
		}

		ps := make([]predicate.ReservationItem, 0, len(fs))
		for i, f := range fs {
			p, err := filterReservationItem(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(reservationitem.Or(ps...))
	}

	if v := req.GetAfter(); v != "" {
		var (
			at0 time.Time
			at1 uuid.UUID
		)
		if err := sqlpage.Decode(v, &at0, &at1); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		p, err := sqlpage.After(orderReservationItem, []any{at0, at1})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), ReservationItemPageSize, ReservationItemPageLimit)
	us, err := q.Order(reservationitem.ByDateCreated(), reservationitem.ById()).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.ReservationItem, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.ReservationItemListResponse_builder{Items: items}.Build()
	if more {
		last := us[len(us)-1]
		next, err := sqlpage.Encode(last.DateCreated, last.Id)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(next)
	}

	return res, nil
}

// filterReservationItem turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterReservationItem(f *rove.ReservationItemFilter) (predicate.ReservationItem, error) {
	ps := make([]predicate.ReservationItem, 0, 1)
	if f.HasRef() {
		p, err := bare.ReservationItemPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasReservation() {
		w := f.GetReservation()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "reservation: %s", err)
			}

			ps = append(ps, reservationitem.ReservationIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.ReservationPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, reservationitem.HasReservationWith(q))
		}
	}
	if f.HasResource() {
		w := f.GetResource()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "resource: %s", err)
			}

			ps = append(ps, reservationitem.ResourceIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.AssetPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, reservationitem.HasResourceWith(q))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return reservationitem.And(ps...), nil
}

