// TenantDomainService is the prefix of every Rpc of that service, which is how a
// change is known to be about a TenantDomain. A service is named for the entity it
// is about, so the name carries it.
var TenantDomainService = watch.ServiceOf(rove.TenantDomainService_Get_FullMethodName)

// Watch answers with the TenantDomains this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkTenantDomain) Watch(req *rove.TenantDomainWatchRequest, out grpc.ServerStreamingServer[rove.TenantDomainWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > TenantDomainFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), TenantDomainFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchTenantDomainKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, TenantDomainService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*rove.TenantDomainWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, rove.TenantDomainWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(rove.TenantDomainWatchResponse_builder{Items: items}.Build())
		})
}

// watchNow sends what matches right now, through the same List a caller
// would have called -- so what a stream begins with and what a list answers
// cannot disagree, and a client does not have to do both and race them.
func (s sinkTenantDomain) watchNow(
	ctx context.Context, req *rove.TenantDomainWatchRequest, out grpc.ServerStreamingServer[rove.TenantDomainWatchResponse],
	sent watch.Seen,
) error {
	after := ""
	for {
		res, err := s.List(ctx, rove.TenantDomainListRequest_builder{
			Filters: req.GetFilters(),
			After:   after,
		}.Build())
		if err != nil {
			return err
		}

		items := make([]*rove.TenantDomainWatchItem, 0, len(res.GetItems()))
		for _, u := range res.GetItems() {
			k, err := pdid.From(u.GetId())
			if err != nil {
				return err
			}

			sent[k] = true
			// No action: this is not something anybody asked for, it is
			// what is already there.
			items = append(items, rove.TenantDomainWatchItem_builder{Id: u.GetId(), Value: u}.Build())
		}
		if len(items) > 0 {
			if err := out.Send(rove.TenantDomainWatchResponse_builder{Items: items}.Build()); err != nil {
				return err
			}
		}

		if after = res.GetNext(); after == "" {
			return nil
		}
	}
}

// watchRead answers with the row as it is now, or nil when it is no longer
// one this caller may see -- erased, walled off, or no longer matching what
// they asked for. The three are deliberately indistinguishable to a caller:
// a stream that told them apart would be saying which rows stopped being
// theirs, which is the thing the wall is for.
//
// The Get is what keeps the wall out of this file. It goes through the same
// server every other read does, with the context of the caller who asked, so
// a row they may not see comes back NotFound and is never sent.
func (s sinkTenantDomain) watchRead(
	ctx context.Context, watching []pdid.Id, k pdid.Id,
) (*rove.TenantDomain, error) {
	// Not one of the rows this stream is about. Asked before the read, so a
	// busy table costs a stream nothing for the rows it does not watch.
	if !slices.Contains(watching, k) {
		return nil, nil
	}

	v, err := s.Get(ctx, rove.TenantDomainGetRequest_builder{
		Ref: rove.TenantDomainRef_builder{Id: k.Bytes()}.Build(),
	}.Build())
	if err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, nil
		}

		return nil, err
	}

	return v, nil
}

// watchTenantDomainKeys is the rows a stream is about, resolved once when it opens.
//
// A filter names a row and a row is named several ways -- by identifier, or
// by whatever unique index the schema declared. Resolving them here rather
// than comparing them per event does three things: the comparison afterwards
// is an identifier against an identifier, a name that names nothing is
// refused when the stream opens rather than silently watching nothing, and a
// row renamed while the stream is open goes on being the row that was asked
// for -- which is what somebody watching a thing meant.
func (s sinkTenantDomain) watchTenantDomainKeys(
	ctx context.Context, fs []*rove.TenantDomainFilter,
) ([]pdid.Id, error) {
	ks := make([]pdid.Id, 0, len(fs))
	for i, f := range fs {
		if !f.HasRef() {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters[%d]: a watch says which rows it is about by naming them", i)
		}

		v, err := s.Get(ctx, rove.TenantDomainGetRequest_builder{Ref: f.GetRef()}.Build())
		if err != nil {
			return nil, err
		}

		k, err := pdid.From(v.GetId())
		if err != nil {
			return nil, err
		}

		ks = append(ks, k)
	}

	return ks, nil
}

type sinkUsageSnapshot struct {
	rove.UsageSnapshotServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) UsageSnapshot() rove.UsageSnapshotServiceServer {
	return sinkUsageSnapshot{s.Server.UsageSnapshot(), s.Server.Store, s.w, s.namer, s.joined}
}

// orderUsageSnapshot is how UsageSnapshots come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderUsageSnapshot = []sqlpage.Order{
	{Column: usagesnapshot.FieldDateCreated, Desc: true},
	{Column: usagesnapshot.FieldId, Desc: true},
}

const (
	// UsageSnapshotPageSize is what a request that did not say gets, and
	// UsageSnapshotPageLimit is the most it gets however loudly it asks.
	UsageSnapshotPageSize  = 31
	UsageSnapshotPageLimit = 400

	// UsageSnapshotFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	UsageSnapshotFilterLimit = 32
)

// List answers with the UsageSnapshots that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkUsageSnapshot) List(ctx context.Context, req *rove.UsageSnapshotListRequest) (*rove.UsageSnapshotListResponse, error) {
	q := s.store.Db.UsageSnapshot.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.UsageSnapshotNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > UsageSnapshotFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), UsageSnapshotFilterLimit)
		}

		ps := make([]predicate.UsageSnapshot, 0, len(fs))
		for i, f := range fs {
			p, err := filterUsageSnapshot(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(usagesnapshot.Or(ps...))
	}

	if v := req.GetAfter(); v != "" {
		var (
			at0 time.Time
			at1 uuid.UUID
		)
		if err := sqlpage.Decode(v, &at0, &at1); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		p, err := sqlpage.After(orderUsageSnapshot, []any{at0, at1})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), UsageSnapshotPageSize, UsageSnapshotPageLimit)
	us, err := q.Order(usagesnapshot.ByDateCreated(sql.OrderDesc()), usagesnapshot.ById(sql.OrderDesc())).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.UsageSnapshot, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.UsageSnapshotListResponse_builder{Items: items}.Build()
	if more {
		last := us[len(us)-1]
		next, err := sqlpage.Encode(last.DateCreated, last.Id)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(next)
	}

	return res, nil
}

// filterUsageSnapshot turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterUsageSnapshot(f *rove.UsageSnapshotFilter) (predicate.UsageSnapshot, error) {
	ps := make([]predicate.UsageSnapshot, 0, 1)
	if f.HasRef() {
		p, err := bare.UsageSnapshotPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasDay() {
		ps = append(ps, usagesnapshot.DayEQ(f.GetDay()))
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return usagesnapshot.And(ps...), nil
}

type sinkWorkOrder struct {
	rove.WorkOrderServiceServer
	store  bare.Store
	w      *watch.Watch
	namer  slug.Namer
	joined bool
}

func (s Sink) WorkOrder() rove.WorkOrderServiceServer {
	return sinkWorkOrder{s.Server.WorkOrder(), s.Server.Store, s.w, s.namer, s.joined}
}

// tenantAtTenant is the tenant "tenant" arrives at.
func (s sinkWorkOrder) tenantAtTenant(ctx context.Context, ref *rove.TenantRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("tenant", "required: it is what says which tenant this belongs to")
	}

	// The row the edge names, picked the way every other reference is.
	pick, err := bare.TenantPick(ref)
	if err != nil {
		return nil, pderr.At("tenant", err)
	}

	k, err := s.store.Db.Tenant.Query().Where(pick).OnlyId(ctx)
	if err != nil {
		// Not there, or more than one -- both are the reference being wrong,
		// and both are the caller's to fix.
		return nil, pderr.Invalidf("tenant", "it does not name one row")
	}

	return k[:], nil
}

// tenantAtAssetTenant is the tenant "asset.tenant" arrives at.
func (s sinkWorkOrder) tenantAtAssetTenant(ctx context.Context, ref *rove.AssetRef) ([]byte, error) {
	if ref == nil {
		return nil, pderr.Invalidf("asset", "required: it is what says which tenant this belongs to")
	}

	// The row the edge names, picked the way every other reference is.
	pick, err := bare.AssetPick(ref)
	if err != nil {
		return nil, pderr.At("asset", err)
	}

	k, err := s.store.Db.Asset.Query().Where(pick).QueryTenant().OnlyId(ctx)
	if err != nil {
		// Not there, or more than one -- both are the reference being wrong,
		// and both are the caller's to fix.
		return nil, pderr.Invalidf("asset", "it does not name one row")
	}

	return k[:], nil
}

// tenancy fills what the schema says this row's tenant is, and refuses a
// row whose other paths do not agree with it.
//
// The request is already this server's copy by the time it arrives, so it
// is written to rather than cloned again.
func (s sinkWorkOrder) tenancy(ctx context.Context, req *rove.WorkOrderAddRequest) error {
	want, err := s.tenantAtTenant(ctx, req.GetTenant())
	if err != nil {
		return err
	}

	if req.HasAsset() {
		got, err := s.tenantAtAssetTenant(ctx, req.GetAsset())
		if err != nil {
			return err
		}
		if string(got) != string(want) {
			// Both exist and both are visible to whoever is writing --
			// the gate already saw to that. What it cannot see is that
			// they are in different tenants, because it asks "may I read
			// this" and a caller who holds several tenants may read both.
			return pderr.Invalidf("asset",
				"it is in another tenant than tenant")
		}
	}

	return nil
}

// Add stamps this row's tenant before writing it.
func (s sinkWorkOrder) Add(ctx context.Context, req *rove.WorkOrderAddRequest) (*rove.WorkOrder, error) {
	// Copied rather than written to: the request belongs to whoever called,
	// and for a call made in this process that is a message they may still
	// be holding.
	r := proto.CloneOf(req)
	if err := s.tenancy(ctx, r); err != nil {
		return nil, err
	}

	return s.WorkOrderServiceServer.Add(ctx, r)
}

// orderWorkOrder is how WorkOrders come back.
//
// The last column is the key, and it is not decoration: a cursor cannot
// tell apart two rows equal in every column of the order, so the page after
// the first of them either repeats the second or skips it. Rows written by
// one request are stamped a moment apart at best.
var orderWorkOrder = []sqlpage.Order{
	{Column: workorder.FieldDateCreated, Desc: true},
	{Column: workorder.FieldId, Desc: true},
}

const (
	// WorkOrderPageSize is what a request that did not say gets, and
	// WorkOrderPageLimit is the most it gets however loudly it asks.
	WorkOrderPageSize  = 100
	WorkOrderPageLimit = 500

	// WorkOrderFilterLimit is how many filters one request may carry. Each is a
	// predicate in the same query, so it is what says how much of the
	// database a request may ask to read -- and it is refused rather than
	// clamped, because dropping half the filters would answer a question
	// nobody asked.
	WorkOrderFilterLimit = 32
)

// List answers with the WorkOrders that match any of the given filters, or with
// every one there is if the request named none, a page at a time.
func (s sinkWorkOrder) List(ctx context.Context, req *rove.WorkOrderListRequest) (*rove.WorkOrderListResponse, error) {
	q := s.store.Db.WorkOrder.Query()

	// Through the same narrowing every generated read goes through, and not
	// by asking the scope alone: what narrows a read is the wall today and
	// the wall and something else tomorrow, and a list that reached past it
	// would be the one read that missed the something else.
	if p, err := bare.WorkOrderNarrow(ctx, s.store.Scope, nil); err != nil {
		return nil, err
	} else if p != nil {
		q.Where(p)
	}

	if fs := req.GetFilters(); len(fs) > 0 {
		if len(fs) > WorkOrderFilterLimit {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters: %d of them, and %d is the most one list carries", len(fs), WorkOrderFilterLimit)
		}

		ps := make([]predicate.WorkOrder, 0, len(fs))
		for i, f := range fs {
			p, err := filterWorkOrder(f)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "filters[%d]: %s", i, err)
			}

			ps = append(ps, p)
		}

		q.Where(workorder.Or(ps...))
	}

	if v := req.GetAfter(); v != "" {
		var (
			at0 time.Time
			at1 uuid.UUID
		)
		if err := sqlpage.Decode(v, &at0, &at1); err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		p, err := sqlpage.After(orderWorkOrder, []any{at0, at1})
		if err != nil {
			return nil, status.Errorf(codes.InvalidArgument, "after: %s", err)
		}

		q.Where(p)
	}

	// One row more than the page, which is how "is there another" is answered
	// without a second query and without a count. The extra is dropped before
	// the answer is built; it was only ever asked for to see whether it was
	// there -- so a full last page answers with no cursor rather than sending
	// the caller back for an empty one.
	size := sqlpage.Size(int(req.GetSize()), WorkOrderPageSize, WorkOrderPageLimit)
	us, err := q.Order(workorder.ByDateCreated(sql.OrderDesc()), workorder.ById(sql.OrderDesc())).Limit(size + 1).All(ctx)
	if err != nil {
		return nil, err
	}

	more := len(us) > size
	if more {
		us = us[:size]
	}

	items := make([]*rove.WorkOrder, len(us))
	for i, u := range us {
		items[i] = u.Proto()
	}

	res := rove.WorkOrderListResponse_builder{Items: items}.Build()
	if more {
		last := us[len(us)-1]
		next, err := sqlpage.Encode(last.DateCreated, last.Id)
		if err != nil {
			return nil, status.Errorf(codes.Internal, "next: %s", err)
		}

		res.SetNext(next)
	}

	return res, nil
}

// filterWorkOrder turns one filter into the predicate that selects what it
// names. Naming nothing is refused, since the request asked for "these" and
// did not say which.
func filterWorkOrder(f *rove.WorkOrderFilter) (predicate.WorkOrder, error) {
	ps := make([]predicate.WorkOrder, 0, 1)
	if f.HasRef() {
		p, err := bare.WorkOrderPick(f.GetRef())
		if err != nil {
			return nil, err
		}

		ps = append(ps, p)
	}
	if f.HasAsset() {
		w := f.GetAsset()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "asset: %s", err)
			}

			ps = append(ps, workorder.AssetIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.AssetPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, workorder.HasAssetWith(q))
		}
	}
	if f.HasStatus() {
		ps = append(ps, workorder.StatusEQ(f.GetStatus()))
	}
	if f.HasKind() {
		ps = append(ps, workorder.KindEQ(f.GetKind()))
	}
	if f.HasVendor() {
		w := f.GetVendor()
		if b := w.GetId(); len(b) > 0 {
			// The **foreign key column** on this row, which is what an
			// edge is. A subquery for a comparison against an indexed
			// column is work nobody asked for.
			k, err := entuuid.FromBytes(b)
			if err != nil {
				return nil, status.Errorf(codes.InvalidArgument, "vendor: %s", err)
			}

			ps = append(ps, workorder.VendorIdEQ(k))
		} else {
			// Named some other way -- an alias, a slug. Resolving it
			// would be a read, and a predicate is built without one, so
			// it becomes a condition on the target instead. One hop,
			// against whatever index that column has.
			q, err := bare.PartyPick(w)
			if err != nil {
				return nil, err
			}

			ps = append(ps, workorder.HasVendorWith(q))
		}
	}
	if len(ps) == 0 {
		return nil, status.Error(codes.InvalidArgument, "a filter that names nothing")
	}

	return workorder.And(ps...), nil
}

// WorkOrderService is the prefix of every Rpc of that service, which is how a
// change is known to be about a WorkOrder. A service is named for the entity it
// is about, so the name carries it.
var WorkOrderService = watch.ServiceOf(rove.WorkOrderService_Get_FullMethodName)

// Watch answers with the WorkOrders this caller may see, as they are now and as
// they change.
//
// What is sent is **state and never a delta**, which is what makes a stream
// that missed something still correct: the next item about a row carries the
// whole of it, so a client converges rather than replays. It is also what
// makes the first message safe to duplicate against the ones after it.
func (s sinkWorkOrder) Watch(req *rove.WorkOrderWatchRequest, out grpc.ServerStreamingServer[rove.WorkOrderWatchResponse]) error {
	ctx := out.Context()

	// A watch with no filters is the whole table, forever. It is the one
	// shape that has no cap at all, so it is the one shape refused.
	fs := req.GetFilters()
	switch {
	case len(fs) == 0:
		return status.Error(codes.InvalidArgument,
			"filters: a watch says which rows it is about; one that says nothing is the whole table, for as long as it is open")
	case len(fs) > WorkOrderFilterLimit:
		return status.Errorf(codes.InvalidArgument,
			"filters: %d of them, and %d is the most one watch carries", len(fs), WorkOrderFilterLimit)
	}

	// Resolved before anything is subscribed to, so a name that names
	// nothing is an answer rather than a stream that quietly watches none.
	watching, err := s.watchWorkOrderKeys(ctx, fs)
	if err != nil {
		return err
	}

	var snapshot func(watch.Seen) error
	if !req.GetSkipSnapshot() {
		snapshot = func(sent watch.Seen) error { return s.watchNow(ctx, req, out, sent) }
	}

	if s.w == nil {
		return status.Error(codes.Unimplemented,
			"this deployment publishes no changes; see WithWatch")
	}

	return watch.Stream(ctx, s.w, WorkOrderService, snapshot,
		func(ks map[pdid.Id]string, sent watch.Seen) error {
			items := make([]*rove.WorkOrderWatchItem, 0, len(ks))
			for k, action := range ks {
				u, err := s.watchRead(ctx, watching, k)
				if err != nil {
					return err
				}
				if u == nil && !sent[k] {
					// Not theirs, or not what they asked for, and they
					// have never been told about it. A row that never
					// matched is not news.
					continue
				}

				sent[k] = u != nil
				items = append(items, rove.WorkOrderWatchItem_builder{
					Id:     k.Bytes(),
					Value:  u,
					Action: action,
				}.Build())
			}
			if len(items) == 0 {
				return nil
			}

			return out.Send(rove.WorkOrderWatchResponse_builder{Items: items}.Build())
		})
}

// watchNow sends what matches right now, through the same List a caller
// would have called -- so what a stream begins with and what a list answers
// cannot disagree, and a client does not have to do both and race them.
func (s sinkWorkOrder) watchNow(
	ctx context.Context, req *rove.WorkOrderWatchRequest, out grpc.ServerStreamingServer[rove.WorkOrderWatchResponse],
	sent watch.Seen,
) error {
	after := ""
	for {
		res, err := s.List(ctx, rove.WorkOrderListRequest_builder{
			Filters: req.GetFilters(),
			After:   after,
		}.Build())
		if err != nil {
			return err
		}

		items := make([]*rove.WorkOrderWatchItem, 0, len(res.GetItems()))
		for _, u := range res.GetItems() {
			k, err := pdid.From(u.GetId())
			if err != nil {
				return err
			}

			sent[k] = true
			// No action: this is not something anybody asked for, it is
			// what is already there.
			items = append(items, rove.WorkOrderWatchItem_builder{Id: u.GetId(), Value: u}.Build())
		}
		if len(items) > 0 {
			if err := out.Send(rove.WorkOrderWatchResponse_builder{Items: items}.Build()); err != nil {
				return err
			}
		}

		if after = res.GetNext(); after == "" {
			return nil
		}
	}
}

// watchRead answers with the row as it is now, or nil when it is no longer
// one this caller may see -- erased, walled off, or no longer matching what
// they asked for. The three are deliberately indistinguishable to a caller:
// a stream that told them apart would be saying which rows stopped being
// theirs, which is the thing the wall is for.
//
// The Get is what keeps the wall out of this file. It goes through the same
// server every other read does, with the context of the caller who asked, so
// a row they may not see comes back NotFound and is never sent.
func (s sinkWorkOrder) watchRead(
	ctx context.Context, watching []pdid.Id, k pdid.Id,
) (*rove.WorkOrder, error) {
	// Not one of the rows this stream is about. Asked before the read, so a
	// busy table costs a stream nothing for the rows it does not watch.
	if !slices.Contains(watching, k) {
		return nil, nil
	}

	v, err := s.Get(ctx, rove.WorkOrderGetRequest_builder{
		Ref: rove.WorkOrderRef_builder{Id: k.Bytes()}.Build(),
	}.Build())
	if err != nil {
		if status.Code(err) == codes.NotFound {
			return nil, nil
		}

		return nil, err
	}

	return v, nil
}

// watchWorkOrderKeys is the rows a stream is about, resolved once when it opens.
//
// A filter names a row and a row is named several ways -- by identifier, or
// by whatever unique index the schema declared. Resolving them here rather
// than comparing them per event does three things: the comparison afterwards
// is an identifier against an identifier, a name that names nothing is
// refused when the stream opens rather than silently watching nothing, and a
// row renamed while the stream is open goes on being the row that was asked
// for -- which is what somebody watching a thing meant.
func (s sinkWorkOrder) watchWorkOrderKeys(
	ctx context.Context, fs []*rove.WorkOrderFilter,
) ([]pdid.Id, error) {
	ks := make([]pdid.Id, 0, len(fs))
	for i, f := range fs {
		if !f.HasRef() {
			return nil, status.Errorf(codes.InvalidArgument,
				"filters[%d]: a watch says which rows it is about by naming them", i)
		}

		v, err := s.Get(ctx, rove.WorkOrderGetRequest_builder{Ref: f.GetRef()}.Build())
		if err != nil {
			return nil, err
		}

		k, err := pdid.From(v.GetId())
		if err != nil {
			return nil, err
		}

		ks = append(ks, k)
	}

	return ks, nil
}

// Gate is the layer that says what a caller may do with a request.
//
// It goes outermost, so nothing behind it has to ask again -- though most
// of what it stands for is not enforced here at all: the wall is a
// predicate and predicates belong in the query, so [Wall] is installed on
// the innermost server. What is left is the two rules that are about a
// row which does not exist yet.
//
//	s, err := app.Build(walled, core.Build(), pd.AuditBuild(), pd.GateBuild())
type Gate struct {
	rove.Overlay
}

func NewGate(next rove.Server) Gate {
	return Gate{rove.NewOverlay(next)}
}

var _ rove.Server = Gate{}

var _ enttx.Binder[rove.Server] = Gate{}

// WithDriver answers with this stack running on `drv`, which is how several
// servers are put on one transaction.
//
// Every layer writes this and none can inherit it: an overlay holds what is
// behind it and has no way to make itself again, so a layer that did not
// write it would be missing from the rebuilt stack and the requests inside
// the transaction would go around it.
func (s Gate) WithDriver(drv dialect.Driver) (rove.Server, error) {
	next, err := enttx.Rebind(s.Next(), drv)
	if err != nil {
		return nil, err
	}

	return NewGate(next), nil
}

// GateBuild makes a builder of this layer so that it can be stacked.
func GateBuild() rove.Builder { return gateBuilder{} }

type gateBuilder struct{}

func (gateBuilder) Build(next rove.Server) (rove.Server, error) {
	return NewGate(next), nil
}

type gateTenant struct {
	Gate
	rove.TenantServiceServer
}

func (s Gate) Tenant() rove.TenantServiceServer {
	return gateTenant{s, s.Next().Tenant()}
}

// Add is not served. A tenant is put up by whoever runs the deployment,
// through a server this layer is not in front of.
func (s gateTenant) Add(ctx context.Context, req *rove.TenantAddRequest) (*rove.Tenant, error) {
	return nil, gate.ErrDeployment("put up")
}

// Erase is not served either, and it would take everything in the tenant
// with it.
func (s gateTenant) Erase(ctx context.Context, req *rove.TenantRef) (*rove.TenantEraseResponse, error) {
	return nil, gate.ErrDeployment("taken down")
}

type gateHolder struct {
	Gate
	rove.HolderServiceServer
}

func (s Gate) Holder() rove.HolderServiceServer {
	return gateHolder{s, s.Next().Holder()}
}

// Add is the one thing about a holder this layer still says, and it is here
// because it is the one that is not a predicate: the row does not exist yet,
// so there is nothing to narrow. Reading one, changing one and erasing one
// are all the wall.
//
// The check is a read of the tenant **through the wall** rather than a
// comparison against the scope, which costs a query and is worth it. A
// reference names a tenant by identifier or by alias, and answering "is this
// one of mine" without a query means holding every tenant in scope in full --
// fine while that is the caller's own and wrong as soon as it is a list a
