// WatchRecorder answers with the recorder that remembers a write for `w`.
//
// It is the other end of the hook the trail hangs off, and it wants the
// opposite thing from that moment: a trail row has to hold or fall with the
// write, so it is written there and then; an event has to be published only
// if the write survived, so nothing is published here at all.
//
//	sink, err := pd.NewSink(db, bare.WithRecorder(pd.WatchRecorder(w)))
func WatchRecorder(w *watch.Watch) bare.Recorder {
	return watchRecorder{w}
}

type watchRecorder struct {
	w *watch.Watch
}

var _ bare.Recorder = watchRecorder{}

func (r watchRecorder) Record(ctx context.Context, _ bare.Server, c bare.Change) error {
	k, err := pdid.From(keyBytes(c.Key))
	if err != nil {
		// A key this app does not make. Nothing to publish about it, and
		// nothing worth failing a write for.
		return nil
	}

	var doc []byte
	if v := hidden(k, c.Patch); v != nil {
		if b, err := proto.Marshal(v); err == nil {
			doc = b
		}
	}

	r.w.Note(ctx, watch.Change{
		Method: c.Method,
		By:     c.By,
		Key:    k,
		Patch:  doc,
	})

	return nil
}

// keyBytes is a key as the sixteen bytes an identifier is.
func keyBytes(v any) []byte {
	switch u := v.(type) {
	case uuid.UUID:
		return u[:]
	case [16]byte:
		return u[:]
	}

	return nil
}

// OutboxRecorder answers with the recorder that writes each write to the
// queue, inside the transaction that makes it.
//
// It is what makes an event survive a process that stops between the commit
// and the publish. `WatchRecorder` remembers in memory and an interceptor
// publishes once the handler has answered; this writes a row, and [Drain]
// publishes it whenever somebody next gets round to it -- which may be after
// a restart, and that is the whole of the point.
//
// Both, for a deployment that wants both: the first is immediate and lossy,
// the second is durable and late. A subscriber sees the same row twice and
// the second time says what the first said, since what is sent is state.
//
//	sink, err := pd.NewSink(db, bare.WithRecorder(pd.OutboxRecorder()))
func OutboxRecorder() bare.Recorder { return outboxRecorder{} }

type outboxRecorder struct{}

var _ bare.Recorder = outboxRecorder{}

// Record writes the row.
//
// Unlike the watch recorder it **refuses** when it cannot, which is the
// difference between the two in one line: this exists so that an event is
// not lost, and letting a write commit whose event could not be queued would
// lose exactly the one it was written to keep.
//
// It writes through `s.Db`, which is the client this transaction is running
// on, and not through a server: there are no Rpcs on this entity, on
// purpose -- see the note in payday's outbox.proto.
func (outboxRecorder) Record(ctx context.Context, s bare.Server, c bare.Change) error {
	k, err := pdid.From(keyBytes(c.Key))
	if err != nil {
		// A key this app does not make, so there is nothing an identifier
		// could say about it and nobody could act on the event.
		return nil
	}

	doc := []byte{}
	if v := hidden(k, c.Patch); v != nil {
		b, err := proto.Marshal(v)
		if err != nil {
			return err
		}

		doc = b
	}

	var actor, tenant pdid.Id
	if f, ok := frame.From(ctx); ok {
		actor = f.Actor
		tenant = f.Tenant
	}

	return s.Db.Outbox.Create().
		SetId(pdid.New(OutboxDomain).Uuid()).
		SetTenantId(tenant.Uuid()).
		SetActorId(actor.Uuid()).
		SetMethod(c.Method).
		SetBy(c.By).
		SetObjectId(k.Uuid()).
		SetPatch(doc).
		Exec(ctx)
}

// DrainSize is how many rows one pass takes.
//
// Bounded because a queue that has been building since a broker went down is
// exactly when a pass must not try to hold all of it, and small enough that
// a pass which fails republishes little.
const DrainSize = 256

// Drain answers with the loop that publishes what the queue holds and takes
// it away.
//
// It is a [spin.Spinner], so it is handed to `spin.Run` with the stack:
//
//	go spin.Run(ctx, slices.Values([]any{pd.Drain(db, broker, time.Second)}))
//
// # It publishes before it deletes
//
// Which is the order that gives at-least-once, and the other order gives
// at-most-once. A process that stops between the two publishes those rows
// again on the next pass, and a subscriber reads the same state twice -- the
// second saying what the first said. That is only harmless because what
// travels is state and not a delta, and it is why an outbox is a table and a
// loop here rather than a project.
//
// # Two replicas publish twice
//
// Nothing here takes a lock, so two of these drain the same rows and publish
// them each. By the paragraph above that is not a correctness problem, and
// it is real work: a deployment that minds runs this on one replica, which
// is a line of wiring rather than a lease to get wrong. Said out loud here
// because the alternative is somebody discovering it from a graph.
func Drain(db *ent.Client, b watch.Broker, every time.Duration) spin.Spinner {
	return drain{db, b, every}
}

type drain struct {
	db    *ent.Client
	b     watch.Broker
	every time.Duration
}

var _ spin.Spinner = drain{}
var _ spin.Named = drain{}

func (drain) SpinName() string { return "outbox" }

func (d drain) Spin(ctx context.Context) error {
	return spin.Every(d.every, d.pass)(ctx)
}

// pass takes one batch, and keeps taking them for as long as it finds a full
// one -- otherwise a queue of ten thousand drains at one batch per tick and
// takes an hour to catch up from a minute of trouble.
//
// It answers nil for a failure rather than ending the loop, and logs it. A
// broker that is down or a database that blinked is a thing to try again;
// giving up would take the process down and stop serving requests that were
// fine. See the note on failure in `payday/spin` -- the loud direction is the
// default there, and this is one of the cases that means the other.
func (d drain) pass(ctx context.Context) error {
	for {
		n, err := d.once(ctx)
		if err != nil {
			log.From(ctx).ErrorContext(ctx, "outbox", slog.String("error", err.Error()))
			return nil
		}
		if n < DrainSize {
			return nil
		}
		if ctx.Err() != nil {
			return nil
		}
	}
}

// once publishes one batch and answers with how many rows were in it.
func (d drain) once(ctx context.Context) (int, error) {
	// Oldest first, which is the order they were written in: an identifier
	// carries the millisecond it was minted and a sequence within it, so the
	// key **is** the order and there is no column to keep in step.
	vs, err := d.db.Outbox.Query().
		Order(outbox.ById()).
		Limit(DrainSize).
		All(ctx)
	if err != nil {
		return 0, err
	}
	if len(vs) == 0 {
		return 0, nil
	}

	ks := make([]uuid.UUID, len(vs))
	for i, v := range vs {
		ks[i] = v.Id
		d.b.Publish(ctx, watch.Event{
			Actor:  pdid.Id(v.ActorId),
			Tenant: pdid.Id(v.TenantId),
			Method: v.Method,
			Changes: []watch.Change{{
				Method: v.Method,
				By:     v.By,
				Key:    pdid.Id(v.ObjectId),
				Patch:  v.Patch,
			}},
		})
	}

	// And only then. A row deleted before it was published is an event that
	// nothing will ever say again.
	if _, err := d.db.Outbox.Delete().
		Where(outbox.IdIn(ks...)).
		Exec(ctx); err != nil {
		return 0, err
	}

	return len(vs), nil
}

// TrailStore is the audit table as [trail.Store] sees it.
//
// Handed to `trail.Sweep` beside a policy, and to whatever command an app
// gives an operator:
//
//	s.Spin = append(s.Spin, trail.Sweep(pd.TrailStore(db), policy))
func TrailStore(db *ent.Client) trail.Store {
	return trailStore{db}
}

type trailStore struct{ db *ent.Client }

var _ trail.Store = trailStore{}

// of narrows to the kinds a read is about, and to whose rows they are.
//
// By the `domain` column and not by the domain byte inside `object_id`,
// which carries the same fact and cannot be indexed: *what kind was this
// row about* is answered by reading a row, and *which rows were about
// robots* is a query over a set. The second is what a retention policy is
// made of.
//
// And by the three tenant columns, which are what the wall on the trail
// reads: a row is readable by every tenant it names, and so it is on each
// of their windows.
func (s trailStore) of(k trail.Scope) *ent.AuditQuery {
	q := s.db.Audit.Query()
	if len(k.Only) > 0 {
		q = q.Where(audit.DomainIn(numbers(k.Only)...))
	} else if len(k.Except) > 0 {
		q = q.Where(audit.DomainNotIn(numbers(k.Except)...))
	}

	if len(k.Objects) > 0 {
		ids := make([]uuid.UUID, len(k.Objects))
		for i, v := range k.Objects {
			ids[i] = v.Uuid()
		}

		q = q.Where(audit.ObjectIdIn(ids...))
	}

	t := k.Tenant.Uuid()
	switch k.Whose {
	case trail.FiledUnder:
		q = q.Where(audit.TenantIdEQ(t))
	case trail.Alone:
		q = q.Where(trailAlone(t))
	case trail.Together:
		q = q.Where(
			audit.Or(audit.TenantIdEQ(t), audit.ActorTenantIdEQ(t), audit.CounterpartTenantIdEQ(t)),
			audit.Not(trailAlone(t)),
		)
	case trail.Sharing:
		q = q.Where(audit.TenantIdEQ(t), audit.Not(trailAlone(t)))
	}

	return q
}

// trailAlone is a row filed under `t` that names no other tenant: the actor
// is of `t` or is nobody, and so is the other party if there is one. Nobody
// is the zero identifier -- the deployment, writing to itself.
func trailAlone(t uuid.UUID) predicate.Audit {
	none := uuid.Nil()

	return audit.And(
		audit.TenantIdEQ(t),
		audit.ActorTenantIdIn(t, none),
		audit.Or(audit.CounterpartTenantIdIsNil(), audit.CounterpartTenantIdIn(t, none)),
	)
}

// Tenants is one seek per tenant: the next `tenant_id` after the last, which
// the index on `(tenant_id, date_created)` answers without reading the rows
// in between. A `DISTINCT` would read all of them.
func (s trailStore) Tenants(ctx context.Context, after pdid.Id, limit int) ([]pdid.Id, error) {
	out := []pdid.Id{}
	last := after.Uuid()
	for len(out) < limit {
		v, err := s.db.Audit.Query().
			Where(audit.TenantIdGT(last)).
			Order(ent.Asc(audit.FieldTenantId)).
			First(ctx)
		if ent.IsNotFound(err) {
			break
		}
		if err != nil {
			return out, err
		}

		out = append(out, pdid.Id(v.TenantId))
		last = v.TenantId
	}

	return out, nil
}

// older is a scope's rows written before `at`, past `after`, oldest first.
func (s trailStore) older(k trail.Scope, at time.Time, after trail.Cursor, limit int) (*ent.AuditQuery, error) {
	q := s.of(k).Where(audit.DateCreatedLT(at))
	if after.Key != nil {
		id, ok := after.Key.(uuid.UUID)
		if !ok {
			return nil, fmt.Errorf("trail: %T is not a key this store gave out", after.Key)
		}

		q = q.Where(audit.Or(
			audit.DateCreatedGT(after.Created),
			audit.And(audit.DateCreatedEQ(after.Created), audit.IdGT(id)),
		))
	}

	return q.
		Order(ent.Asc(audit.FieldDateCreated, audit.FieldId)).
		Limit(limit), nil
}

func (s trailStore) Older(ctx context.Context, k trail.Scope, at time.Time, after trail.Cursor, limit int) (trail.Rows, error) {
	q, err := s.older(k, at, after, limit)
	if err != nil {
		return nil, err
	}

	vs, err := q.All(ctx)
	if err != nil {
		return nil, err
	}

	out := make(trail.Rows, 0, len(vs))
	for _, v := range vs {
		b, err := protojson.Marshal(v.Proto())
		if err != nil {
			return nil, err
		}

		out = append(out, trail.Row{
			Doc:     b,
			Key:     v.Id,
			Domain:  pdid.Domain(v.Domain),
			Created: v.DateCreated,
			Tenants: trail.TenantsOf(v.TenantId, v.ActorTenantId, v.CounterpartTenantId),
		})
	}

	return out, nil
}

// Heads is the same rows with only what a decision about them reads: no
// `value`, no `patch`, and nothing marshalled.
func (s trailStore) Heads(ctx context.Context, k trail.Scope, at time.Time, after trail.Cursor, limit int) (trail.Rows, error) {
	q, err := s.older(k, at, after, limit)
	if err != nil {
		return nil, err
	}

	vs, err := q.Select(
		audit.FieldId,
		audit.FieldDateCreated,
		audit.FieldDomain,
		audit.FieldTenantId,
		audit.FieldActorTenantId,
		audit.FieldCounterpartTenantId,
	).All(ctx)
	if err != nil {
		return nil, err
	}

	out := make(trail.Rows, 0, len(vs))
	for _, v := range vs {
		out = append(out, trail.Row{
			Key:     v.Id,
			Domain:  pdid.Domain(v.Domain),
			Created: v.DateCreated,
			Tenants: trail.TenantsOf(v.TenantId, v.ActorTenantId, v.CounterpartTenantId),
		})
	}

	return out, nil
}

func (s trailStore) Count(ctx context.Context, k trail.Scope, at time.Time) (int, error) {
	return s.of(k).Where(audit.DateCreatedLT(at)).Count(ctx)
}

// Forget removes exactly the rows these keys name.
//
// By identifier and not by the cutoff again, which is the whole of what
// makes the archive trustworthy: a second query matches whatever is true
// when it runs, and a row backdated by a clock that stepped is one it
// removes and the archive does not have.
func (s trailStore) Forget(ctx context.Context, keys []any) (int, error) {
	ids, err := trailKeys(keys)
	if err != nil {
		return 0, err
	}

	return s.db.Audit.Delete().Where(audit.IdIn(ids...)).Exec(ctx)
}

// Blank empties the two columns that hold contents, for exactly these rows.
//
// Empty and not nil: nil is SQL NULL, which a NOT NULL column refuses on
// PostgreSQL and accepts on SQLite.
func (s trailStore) Blank(ctx context.Context, keys []any) (int, error) {
	ids, err := trailKeys(keys)
	if err != nil {
		return 0, err
	}

	return s.db.Audit.Update().
		Where(audit.IdIn(ids...)).
		SetValue([]byte{}).
		SetPatch([]byte{}).
		Save(ctx)
}

// trailKeys is the keys this store gave out, back as what it deletes by.
func trailKeys(keys []any) ([]uuid.UUID, error) {
	ids := make([]uuid.UUID, 0, len(keys))
	for _, k := range keys {
		v, ok := k.(uuid.UUID)
		if !ok {
			return nil, fmt.Errorf("trail: %T is not a key this store gave out", k)
		}

		ids = append(ids, v)
	}

	return ids, nil
}

// numbers is what the column holds, which is a domain widened to what
// protobuf has: there is no `uint8`.
func numbers(ds []pdid.Domain) []uint32 {
	out := make([]uint32, len(ds))
	for i, d := range ds {
		out[i] = uint32(d)
	}

	return out
}

// archivedCounter is the manifest's one row that is not a blob: the number
// of the latest checkpoint, whose row lock is what keeps two checkpoints
// from taking one number.
var archivedCounter = uuid.Nil()

func (s trailStore) Adding(ctx context.Context, ns, intent string, labels map[string]string) (any, error) {
	v, err := s.db.Archived.Create().
		SetId(pdid.New(ArchivedDomain).Uuid()).
		SetNamespace(ns).
		SetDigest("").
		SetIntent(intent).
		SetLabels(labels).
		SetState(trail.Adding).
		SetSince(0).
		SetGone(0).
		SetDateUpdated(time.Now()).
		Save(ctx)
	if err != nil {
		return nil, err
	}

	return v.Id, nil
}

func (s trailStore) Added(ctx context.Context, key any, digest string, labels map[string]string) error {
	id, ok := key.(uuid.UUID)
	if !ok {
		return fmt.Errorf("trail: %T is not a key this store gave out", key)
	}

	return s.db.Archived.UpdateOneId(id).
		SetDigest(digest).
		SetLabels(labels).
		SetState(trail.Present).
		SetDateUpdated(time.Now()).
		Exec(ctx)
}

func (s trailStore) Drop(ctx context.Context, key any) error {
	id, ok := key.(uuid.UUID)
	if !ok {
		return fmt.Errorf("trail: %T is not a key this store gave out", key)
	}

	_, err := s.db.Archived.Delete().Where(archived.IdEQ(id), archived.StateEQ(trail.Adding)).Exec(ctx)
	return err
}

func (s trailStore) Mark(ctx context.Context, ns, digest, from, to string) error {
	_, err := s.db.Archived.Update().
		Where(archived.NamespaceEQ(ns), archived.DigestEQ(digest), archived.StateEQ(from)).
		SetState(to).
		SetDateUpdated(time.Now()).
		Save(ctx)
	return err
}

func (s trailStore) Label(ctx context.Context, ns, digest string, labels map[string]string) error {
	_, err := s.db.Archived.Update().
		Where(archived.NamespaceEQ(ns), archived.DigestEQ(digest), archived.StateNEQ(trail.Erased)).
		SetLabels(labels).
		Save(ctx)
	return err
}

func (s trailStore) Rows(ctx context.Context) ([]trail.Archived, error) {
	vs, err := s.db.Archived.Query().
		Where(archived.NamespaceNEQ(""), archived.StateNEQ(trail.Erased)).
		All(ctx)
	if err != nil {
		return nil, err
	}

	return archivedRows(vs), nil
}

// Checkpoint is one transaction, and the counter's row is the first thing it
// writes: a second checkpoint waits on that row until the first has
// committed, and then takes the next number.
func (s trailStore) Checkpoint(ctx context.Context) (int, []trail.Archived, error) {
	tx, err := s.db.Tx(ctx)
	if err != nil {
		return 0, nil, err
	}
	defer tx.Rollback()

	n, err := tx.Archived.Update().Where(archived.IdEQ(archivedCounter)).AddSince(1).SetDateUpdated(time.Now()).Save(ctx)
	if err != nil {
		return 0, nil, err
	}
	if n == 0 {
		// The first. Two at once both try, and one is refused for the key.
		if err := tx.Archived.Create().
			SetId(archivedCounter).
			SetNamespace("").
			SetDigest("").
			SetIntent("").
			SetLabels(map[string]string{}).
			SetState("counter").
			SetSince(1).
			SetGone(0).
			SetDateUpdated(time.Now()).
			Exec(ctx); err != nil {
			return 0, nil, err
		}
	}

	c, err := tx.Archived.Get(ctx, archivedCounter)
	if err != nil {
		return 0, nil, err
	}
	k := c.Since

	// In it from now on: what was added since the last one.
	if _, err := tx.Archived.Update().
		Where(archived.NamespaceNEQ(""), archived.StateIn(trail.Present, trail.Erasing), archived.SinceEQ(0)).
		SetSince(k).
		Save(ctx); err != nil {
		return 0, nil, err
	}

	// Out of it from now on: what was erased since.
	if _, err := tx.Archived.Update().
		Where(archived.NamespaceNEQ(""), archived.StateEQ(trail.Erased), archived.GoneEQ(0), archived.SinceGT(0)).
		SetGone(k).
		Save(ctx); err != nil {
		return 0, nil, err
	}

	// And what no checkpoint read back any more was in: erased before one
	// saw it, or gone before the one before this.
	if _, err := tx.Archived.Delete().
		Where(
			archived.NamespaceNEQ(""),
			archived.StateEQ(trail.Erased),
			archived.Or(archived.SinceEQ(0), archived.And(archived.GoneGT(0), archived.GoneLT(k))),
		).
		Exec(ctx); err != nil {
		return 0, nil, err
	}

	vs, err := tx.Archived.Query().Where(archivedAt(k)).All(ctx)
	if err != nil {
		return 0, nil, err
	}

	return int(k), archivedRows(vs), tx.Commit()
}

func (s trailStore) At(ctx context.Context, k int) ([]trail.Archived, error) {
	vs, err := s.db.Archived.Query().Where(archivedAt(uint32(k))).All(ctx)
	if err != nil {
		return nil, err
	}

	return archivedRows(vs), nil
}

func (s trailStore) Latest(ctx context.Context) (int, time.Time, error) {
	c, err := s.db.Archived.Get(ctx, archivedCounter)
	if ent.IsNotFound(err) {
		return 0, time.Time{}, nil
	}
	if err != nil {
		return 0, time.Time{}, err
	}

	return int(c.Since), c.DateUpdated, nil
}

// archivedAt is the rows a checkpoint was taken over: in it by then, and
// not gone by then.
func archivedAt(k uint32) predicate.Archived {
	return archived.And(
		archived.NamespaceNEQ(""),
		archived.SinceGT(0),
		archived.SinceLTE(k),
		archived.Or(archived.GoneEQ(0), archived.GoneGT(k)),
	)
}

func archivedRows(vs []*ent.Archived) []trail.Archived {
	out := make([]trail.Archived, 0, len(vs))
	for _, v := range vs {
		out = append(out, trail.Archived{
			Key:       v.Id,
			Namespace: v.Namespace,
			Digest:    v.Digest,
			Intent:    v.Intent,
			Labels:    v.Labels,
			State:     v.State,
			Since:     int(v.Since),
			Gone:      int(v.Gone),
			Created:   v.DateCreated,
			Updated:   v.DateUpdated,
		})
	}

	return out
}

// TrailOf is a reader of the archive's documents as the messages they hold:
// what `policy.Read` and `policy.ReadTenant` are handed, and `trail.Read`,
// `trail.ReadTenant` and `trail.ReadFiles`, which check nothing.
//
//	err := policy.ReadTenant(ctx, store, tenant, pd.TrailOf(func(v *app.Audit) error {
//		...
//	}))
//
// The runtime hands over documents, because it has no `Audit` type to
// unmarshal into. This is the half that does.
//
// It opens no database, deliberately: what an archive is for is outliving
// the deployment that wrote it, and a reader that needed the deployment
// would be answering the question at the one moment nobody can.
func TrailOf(fn func(*rove.Audit) error) func(doc []byte) error {
	return func(doc []byte) error {
		v := &rove.Audit{}
		if err := protojson.Unmarshal(doc, v); err != nil {
			return err
		}

		return fn(v)
	}
}

// Batch answers with the server that runs several writes as one
// transaction.
//
// The guard is required and there is no default for it. Everything payday
// enforces by method name is enforced against `BatchService/Do` and not
// against what it carries, so a batch built without one is a way past all
// of it -- a caller whose credential allows one method wraps whatever they
// like in a batch, and the trail records that it was allowed.
//
//	b, err := pd.Batch(s.Walled, s.Drv, c.Server.Guard(policy))
//
// The guard comes from the configuration rather than being written out,
// which is what keeps it saying the same thing the interceptors say. Two
// places deciding what is closed will disagree, and the direction they
// disagree in is the one where the batch allows more.
//
// The driver is passed rather than taken from the server, because the
// transaction is begun on it and a `*ent.Client` does not hand out the
// driver it was built with. The app has one: it is what it built the client
// from.
func Batch(s rove.Server, drv dialect.Driver, guard batch.Guard) (pdpb.BatchServiceServer, error) {
	if guard.IsZero() {
		// Nobody filled it in. It is the zero value and not a judgement about
		// how open the deployment is: `config.ServerConfig.Guard` always sets
		// how a caller is counted, so a deployment that closes nothing and
		// limits nothing still comes through here with something in it.
		//
		// Refused rather than served open, because served open is a privilege
		// escalation and the way it would be found is somebody reading the
		// wiring and noticing what is not there.
		return nil, batch.ErrNoGuard
	}

	return batchServer{s: s, drv: drv, guard: guard}, nil
}

type batchServer struct {
	pdpb.UnimplementedBatchServiceServer

	s     rove.Server
	drv   dialect.Driver
	guard batch.Guard
}

// Do runs every operation in one transaction.
//
// The transaction is opened here and the whole stack is put on it, so the
// layers each operation goes through are the same objects with the same
// rules -- the wall still narrows, the trail is still written, the outbox
// still gets its row. What changes is only which driver they are talking
// to.
//
// Nothing is published until it commits. The watch recorder remembers into
// the context and the interceptor publishes once this handler has answered,
// which is after the commit -- so a batch arrives at a subscriber as one
// event holding every change, which is what it was.
func (b batchServer) Do(ctx context.Context, req *pdpb.BatchRequest) (*pdpb.BatchResponse, error) {
	ops := req.GetOps()
	if err := b.guard.Check(len(ops)); err != nil {
		return nil, err
	}

	// Every rule for every operation, before anything is written. The
	// transaction would undo the work of a batch refused halfway, but the
	// work and the locks it took are real -- and a rate limiter that had
	// already counted the first seven would charge for a batch that never
	// happened.
	cs := make([]context.Context, len(ops))
	for i, op := range ops {
		c, err := b.guard.Allow(ctx, op.GetMethod())
		if err != nil {
			return nil, batch.Failed(i, op.GetMethod(), err)
		}

		cs[i] = c
	}

	drv, tx, err := dialect.BeginTx(ctx, b.drv)
	if err != nil {
		return nil, err
	}

	s, err := enttx.Rebind(b.s, drv)
	if err != nil {
		tx.Rollback()
		return nil, err
	}

	vs := make([]*anypb.Any, len(ops))
	for i, op := range ops {
		v, err := dispatch(cs[i], s, op)
		if err != nil {
			tx.Rollback()
			return nil, batch.Failed(i, op.GetMethod(), err)
		}

		vs[i] = v
	}

	if err := tx.Commit(); err != nil {
		return nil, err
	}

	return pdpb.BatchResponse_builder{Results: vs}.Build(), nil
}

